-- Update category assignments for the existing 171 products from the five supplied catalog lists.
-- Each product is assigned three closest existing subcategories; accessory coverage includes four additions in migration 010.
-- This changes category fields/links and updated_at only. It does NOT alter visibility or create product rows.
-- Run in phpMyAdmin against the live storefront database. Re-running reapplies the same assignments.
START TRANSACTION;
-- Add four useful subcategories under the existing Accessories menu.
SELECT p.id, s.name, s.slug, s.position
FROM product_categories p
JOIN (
  SELECT 'Desktop Computers' AS name, 'desktop-computers' AS slug, 9 AS position UNION ALL
  SELECT 'Projectors', 'projectors', 10 UNION ALL
  SELECT 'UPS & Power Protection', 'ups-power-protection', 11 UNION ALL
  SELECT 'Networking Equipment', 'network-equipment', 12
) s ON p.slug = 'accessories' AND p.parent_id IS NULL;
CREATE TEMPORARY TABLE tmp_product_category_map (title VARCHAR(255) NOT NULL PRIMARY KEY, primary_slug VARCHAR(120) NULL, slugs VARCHAR(1200) NOT NULL) ENGINE=InnoDB;
UPDATE tmp_product_category_map SET primary_slug = 'business-laptops', slugs = 'business-laptops,brand-new-laptops,student-laptops' WHERE title = 'HP ProBook 440 G11';
SELECT COUNT(DISTINCT p.id) AS matched_existing_products FROM products p JOIN tmp_product_category_map m ON m.title = p.title;
UPDATE products p JOIN tmp_product_category_map m ON m.title = p.title LEFT JOIN product_categories c ON c.slug = m.primary_slug AND c.is_active = 1 SET p.category_id = c.id, p.category = c.name, p.updated_at = NOW();
DELETE pcl FROM product_category_links pcl JOIN products p ON p.id = pcl.product_id JOIN tmp_product_category_map m ON m.title = p.title;
COMMIT;
SELECT m.title, p.category, p.category_id, GROUP_CONCAT(c.slug ORDER BY c.parent_id IS NULL, c.position SEPARATOR ' | ') AS assigned_categories FROM tmp_product_category_map m JOIN products p ON p.title = m.title LEFT JOIN product_category_links pcl ON pcl.product_id = p.id LEFT JOIN product_categories c ON c.id = pcl.category_id GROUP BY p.id, m.title, p.category, p.category_id ORDER BY m.title;
DROP TEMPORARY TABLE tmp_product_category_map;