INSERT IGNORE INTO product_category_links (product_id, category_id) SELECT p.id, c.id FROM products p JOIN tmp_product_category_map m ON m.title = p.title JOIN product_categories c ON FIND_IN_SET(c.slug, m.slugs) > 0 AND c.is_active = 1;
